referenceSolutions.javascript:
export function updateMatrix(matrix            )             {
  const rows = matrix.length, cols = matrix[0].length; const distances             = matrix.map(row => row.map(value => value === 0 ? 0 : -1)); const queue             = []; for (let r=0;r<rows;r++) for (let c=0;c<cols;c++) if (matrix[r][c]===0) queue.push([r,c]); for (let i=0;i<queue.length;i++) { const [r,c]=queue[i]; for (const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) { const nr=r+dr,nc=c+dc; if(nr>=0&&nr<rows&&nc>=0&&nc<cols&&distances[nr][nc]===-1) { distances[nr][nc]=distances[r][c]+1; queue.push([nr,nc]); } } } return distances;
}

